CREATE TABLE public.assignment_mark_drafts (submission_id uuid PRIMARY KEY REFERENCES public.assignment_submissions(id) ON DELETE CASCADE, score integer, feedback text NOT NULL DEFAULT '', trainer_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.assignment_mark_drafts TO authenticated;
GRANT ALL ON public.assignment_mark_drafts TO service_role;
ALTER TABLE public.assignment_mark_drafts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Course instructors read mark drafts" ON public.assignment_mark_drafts FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.assignment_submissions s JOIN public.assignments a ON a.id = s.assignment_id WHERE s.id = submission_id AND public.teaches(auth.uid(), a.course_slug)));
CREATE POLICY "Course instructors create mark drafts" ON public.assignment_mark_drafts FOR INSERT TO authenticated WITH CHECK (trainer_id = auth.uid() AND EXISTS (SELECT 1 FROM public.assignment_submissions s JOIN public.assignments a ON a.id = s.assignment_id WHERE s.id = submission_id AND public.teaches(auth.uid(), a.course_slug) AND (score IS NULL OR score BETWEEN 0 AND a.max_score)));
CREATE POLICY "Course instructors edit mark drafts" ON public.assignment_mark_drafts FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.assignment_submissions s JOIN public.assignments a ON a.id = s.assignment_id WHERE s.id = submission_id AND public.teaches(auth.uid(), a.course_slug))) WITH CHECK (trainer_id = auth.uid() AND EXISTS (SELECT 1 FROM public.assignment_submissions s JOIN public.assignments a ON a.id = s.assignment_id WHERE s.id = submission_id AND public.teaches(auth.uid(), a.course_slug) AND (score IS NULL OR score BETWEEN 0 AND a.max_score)));
CREATE POLICY "Course instructors remove mark drafts" ON public.assignment_mark_drafts FOR DELETE TO authenticated USING (EXISTS (SELECT 1 FROM public.assignment_submissions s JOIN public.assignments a ON a.id = s.assignment_id WHERE s.id = submission_id AND public.teaches(auth.uid(), a.course_slug)));
CREATE OR REPLACE FUNCTION public.touch_assignment_mark_draft() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END $$;
CREATE TRIGGER touch_assignment_mark_draft BEFORE UPDATE ON public.assignment_mark_drafts FOR EACH ROW EXECUTE FUNCTION public.touch_assignment_mark_draft();